// Target products scanned on every run. Edit queries here.
const targets = [
 { key: 'apple_20w', name_fa: 'آداپتور ۲۰ وات اپل', torob_query: 'آداپتور 20 وات اپل اصلی', torob_condition: 'new', shop_query: 'آداپتور 20 وات اپل', divar_query: 'آداپتور 20 وات اپل اصلی', divar_category: null },
 { key: 'dualsense', name_fa: 'دسته PS5 DualSense', torob_query: 'دسته dualsense ps5', torob_condition: 'new', shop_query: 'دسته بازی DualSense PS5', divar_query: 'دسته dualsense', divar_category: null },
 { key: 'nvme_1tb', name_fa: 'اساسدی NVMe یک ترابایت', torob_query: 'ssd nvme 1tb', torob_condition: 'new', shop_query: 'اس اس دی NVMe 1 ترابایت', divar_query: 'ssd nvme 1tb', divar_category: null },
 { key: 'used_iphone', name_fa: 'آیفون کارکرده تمیز', torob_query: 'آیفون 13 128 گیگابایت', torob_condition: 'used', shop_query: 'آیفون 13 128 گیگابایت', divar_query: 'آیفون 13 128 تمیز', divar_category: 'mobile-phones' },
];
return targets.map(t => ({ json: t }));

const MIN_MARGIN = 18;
const BUDGET = 100000000;
const DIVAR_FLOOR = 0.4;
const DEDUPE_HOURS = 6;

function parseMcp(j) {
 if (!j || typeof j !== 'object') return {};
 if (Array.isArray(j.content)) {
 for (const c of j.content) {
 if (c && c.type === 'text' && typeof c.text === 'string') {
 try { return JSON.parse(c.text); } catch (e) {}
 }
 }
 }
 if (typeof j.text === 'string') { try { return JSON.parse(j.text); } catch (e) {} }
 if (j.result && typeof j.result === 'object') return parseMcp(j.result);
 return j;
}
const toNum = v => { const n = Number(String(v ?? '').replace(/[^0-9.]/g, '')); return Number.isFinite(n) && n > 0 ? n : null; };
const fmt = n => Math.round(n).toLocaleString('en-US');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let usdToman = null;
try {
 const fx = parseMcp($('Get USD Rate (tgju)').first().json);
 const rows = fx.rows || fx.data || fx.prices || [];
 const usd = rows.find(r => /dollar/i.test(String(r.symbol || '')) || String(r.name || '').includes('دلار'));
 if (usd) usdToman = toNum(usd.price_toman ?? usd.toman ?? usd.price);
} catch (e) {}

const targets = $('Build Target List').all();
const pick = (name, i) => { try { return parseMcp($(name).all()[i]?.json); } catch (e) { return {}; } };
const store = $getWorkflowStaticData('global');
store.alerted = store.alerted || {};
const now = Date.now();
for (const k of Object.keys(store.alerted)) if (now - store.alerted[k] > DEDUPE_HOURS * 3600e3) delete store.alerted[k];

const out = [];
targets.forEach((t, i) => {
 const target = t.json;
 const tb = pick('Torob Market Baseline', i);
 const picksArr = Array.isArray(tb.picks) ? tb.picks : [];
 const ref = picksArr.find(p => p && p.stats && toNum(p.stats.median)) || null;
 const market = ref ? toNum(ref.stats.median) : null;
 if (!market) return;

 const candidates = [];
 const dk = pick('Digikala Cheapest', i);
 for (const p of (dk.products || []).slice(0, 3)) {
 const cost = toNum(p.price);
 if (cost && p.in_stock !== false) candidates.push({ source: 'دیجیکالا', title: p.title, cost, before: toNum(p.price_before_discount), discount: p.discount_pct || 0, link: p.url, flash: p.deal_ends || null });
 }
 const tl = pick('Technolife Flash Prices', i);
 for (const p of (tl.products || []).slice(0, 3)) {
 const cost = toNum(p.final_price ?? p.price);
 if (cost && p.in_stock !== false) candidates.push({ source: 'تکنولایف', title: p.title, cost, before: toNum(p.price), discount: p.discount_pct || 0, link: p.url, flash: p.deal_ends || p.deal || null });
 }
 const dv = pick('Divar Urgent Used Ads', i);
 const ads = dv.ads || dv.results || dv.posts || [];
 for (const a of ads.slice(0, 20)) {
 const cost = toNum(a.price);
 if (cost && cost >= market * DIVAR_FLOOR) candidates.push({ source: 'دیوار (دست دوم)', title: a.title, cost, before: null, discount: 0, link: a.url, flash: a.tag || null });
 }

 for (const c of candidates) {
 const netProfit = market - c.cost;
 const margin = (netProfit / c.cost) * 100;
 const discountVerified = c.before ? c.before > c.cost : c.discount === 0;
 const isDeal = margin >= MIN_MARGIN && discountVerified && c.cost <= BUDGET;
 const dedupeKey = c.link + '|' + c.cost;
 const isNew = !store.alerted[dedupeKey];
 const units = Math.floor(BUDGET / c.cost);
 const message = [
 '🔥 <b>فرصت بلک فرایدی ۲۰۲۶</b>',
 '',
 '📦 <b>محصول:</b> ' + esc(target.name_fa),
 '🏷 <b>آگهی:</b> ' + esc(c.title),
 '🏪 <b>منبع:</b> ' + esc(c.source),
 '💰 <b>قیمت خرید:</b> ' + fmt(c.cost) + ' تومان',
 '📊 <b>قیمت بازار (میانه ترب):</b> ' + fmt(market) + ' تومان',
 '✅ <b>سود خالص:</b> ' + fmt(netProfit) + ' تومان',
 '📈 <b>حاشیه سود:</b> ' + margin.toFixed(1) + '٪',
 c.discount ? '🎯 <b>تخفیف اعلامی:</b> ' + c.discount + '٪' : '',
 usdToman ? '💵 <b>معادل دلاری خرید:</b> $' + (c.cost / usdToman).toFixed(1) + ' (دلار ' + fmt(usdToman) + ')' : '',
 '🧮 <b>حداکثر تعداد با بودجه:</b> ' + units + ' عدد',
 c.flash ? '⏳ <b>کمپین:</b> ' + esc(c.flash) : '',
 '',
 '🔗 <a href="' + esc(c.link) + '">لینک خرید مستقیم</a>',
 ].filter(Boolean).join('\n');
 if (isDeal && isNew) store.alerted[dedupeKey] = now;
 out.push({ json: {
 product_key: target.key, product_name: target.name_fa, listing_title: c.title, source: c.source,
 discounted_cost: c.cost, market_price: market, net_profit: netProfit,
 profit_margin_pct: Math.round(margin * 10) / 10, discount_verified: discountVerified,
 usd_toman: usdToman, buy_link: c.link, is_deal: isDeal, is_new_alert: isNew, message_fa: message,
 } });
 }
});
return out;
